<script setup lang="ts">import{onMounted,ref}from'vue';import{ElMessage}from'element-plus';import{request}from'../../api/client';import DramaCard from'../../components/DramaCard.vue';const dramas=ref<any[]>([]);async function load(){try{const j=await request('/api/v1/dramas?page=1&page_size=50');dramas.value=j.items||[]}catch{ElMessage.warning('API 未启动，请先启动 drama-api')}}onMounted(load)</script>
<template><section><div class="page-title"><p class="eyebrow">DISCOVER</p><h1>Find your next obsession</h1><p>Browse the global short-drama catalog.</p></div><div class="grid"><DramaCard v-for="x in dramas" :key="x.drama_id" :drama="x"/></div><el-empty v-if="!dramas.length" description="暂无目录数据"/></section></template>